function buildWalkPath(points,width,height,origin){
 const xScale=width/100,yScale=height/100,segments=[];let totalLength=0,closestDistance=Infinity,startDistance=0;
 const originX=origin[0]*xScale,originY=origin[1]*yScale;
 for(let index=0;index<points.length;index++){
  const a=points[index],b=points[(index+1)%points.length],ax=a[0]*xScale,ay=a[1]*yScale,bx=b[0]*xScale,by=b[1]*yScale,dx=bx-ax,dy=by-ay,length=Math.hypot(dx,dy);
  if(length<0.01)continue;
  const progress=Math.max(0,Math.min(1,((originX-ax)*dx+(originY-ay)*dy)/(length*length))),nearestX=ax+dx*progress,nearestY=ay+dy*progress,distance=Math.hypot(originX-nearestX,originY-nearestY);
  if(distance<closestDistance){closestDistance=distance;startDistance=totalLength+length*progress}
  segments.push({a,b,length});totalLength+=length;
 }
 return {segments,totalLength,startDistance,closestDistance,width,height};
}
function pointOnWalkPath(path,distance){
 if(!path?.totalLength)return null;
 let remaining=((distance%path.totalLength)+path.totalLength)%path.totalLength;
 for(const segment of path.segments){
  if(remaining<=segment.length){
   const progress=remaining/segment.length;
   return {x:segment.a[0]+(segment.b[0]-segment.a[0])*progress,y:segment.a[1]+(segment.b[1]-segment.a[1])*progress,dx:segment.b[0]-segment.a[0]};
  }
  remaining-=segment.length;
 }
 return null;
}
