 async function syncHermesReply(groupId){
  if(!sourceProviders.Hermes?.connected){setNotice('請先連接 Hermes，再同步工作階段回覆。');return}
  const targetGroup=groups.find(item=>item.id===groupId);if(!targetGroup){setNotice('找不到這個群組。');return}
  const sessionId=targetGroup.hermesSessionId||`ai-office-${activeOffice.id}-${groupId}`;setHermesSyncBusy(true);
  try{
   const response=await fetch('/api/integrations/hermes/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sessionIds:[sessionId]})}),data=await response.json();if(!response.ok)throw new Error(data.error||'讀取 Hermes 工作階段失敗。');
   const session=(data.sessions||[]).find(item=>item.id===sessionId);if(!session)throw new Error('Hermes 找不到這個 API 工作階段。');
   const local=messages[groupId]||[],known=new Set(local.filter(message=>message.source==='Hermes'&&message.sender!=='user').map(message=>`${message.time||''}\n${message.text}`));
   const missing=(session.messages||[]).filter(message=>message.role==='assistant'&&!known.has(`${message.time||''}\n${message.text}`));
   if(!missing.length){setNotice('已同步 Hermes；目前沒有尚未顯示的新回覆。');return}
   const replies=missing.map(message=>({id:crypto.randomUUID(),sender:targetGroup.members[0]||groupId,text:message.text,time:message.time||'Hermes',source:'Hermes',model:sourceProviders.Hermes.model}));
   setMessages(previous=>{const current=previous[groupId]||[],seen=new Set(current.filter(message=>message.source==='Hermes'&&message.sender!=='user').map(message=>`${message.time||''}\n${message.text}`)),fresh=replies.filter(message=>!seen.has(`${message.time||''}\n${message.text}`));return fresh.length?{...previous,[groupId]:[...current,...fresh]}:previous});
   setNotice(`已從 Hermes 同步 ${missing.length} 則回覆。`);
  }catch(error){setNotice(`同步 Hermes 失敗：${error.message}`)}finally{setHermesSyncBusy(false)}
 }
